"use client";

import * as React from "react";

type DivProps = React.ComponentProps<"div">;

export type ReadAlongTone = "chart-1" | "chart-2" | "chart-3" | "chart-4" | "chart-5";
export type ReadAlongSize = "md" | "lg";
export type ReadAlongWordState = "upcoming" | "current" | "done";

export type ReadAlongWord = {
  /** The word as written, punctuation attached. */
  text: string;
  /** Position across all paragraphs. */
  index: number;
  paragraph: number;
  sentence: number;
  /** Extra pause in milliseconds after this word in the generated schedule. */
  pause: number;
};

export type ReadAlongSchedule = { words: ReadAlongWord[]; timings: number[]; duration: number };

export type ReadAlongScheduleOptions = {
  /** Words per second when no timings are given. */
  wordsPerSecond?: number;
  /** Milliseconds added after sentence-ending punctuation; half of it after commas, semicolons and colons. */
  punctuationPause?: number;
  /** Seconds of silence before the first word. */
  leadIn?: number;
};

export type ReadAlongTextProps = DivProps & {
  text: string | string[];
  /** 0..1 position in the speech. */
  progress?: number;
  /** Seconds into the speech; pair with `duration` and, when you have them, `timings`. */
  currentTime?: number;
  duration?: number;
  /** Start time of every word in seconds (one entry per word). */
  timings?: number[];
  /** Convenience clock: while true the component advances time itself and reports it through `onProgressChange`. */
  playing?: boolean;
  wordsPerSecond?: number;
  punctuationPause?: number;
  leadIn?: number;
  onProgressChange?: (progress: number, time: number) => void;
  onWord?: (index: number, word: string) => void;
  onSeek?: (index: number, time: number, progress: number) => void;
  onEnd?: () => void;
  tone?: ReadAlongTone;
  size?: ReadAlongSize;
  dimUpcoming?: boolean;
  caret?: boolean;
};

type Box = { left: number; top: number; width: number };

const SENTENCE_END = /[.!?…]+["'”’)\]]*$/;
const CLAUSE_END = /[,;:]+["'”’)\]]*$/;
const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const CARET_GAP = 4;
const CARET_SLIDE = 180;
const CARET_FLIGHT = 260;
const HIGHLIGHT_GROW = 220;

const TONE = {
  "chart-1": { caret: "bg-chart-1", highlight: "bg-chart-1/15 dark:bg-chart-1/30" },
  "chart-2": { caret: "bg-chart-2", highlight: "bg-chart-2/15 dark:bg-chart-2/30" },
  "chart-3": { caret: "bg-chart-3", highlight: "bg-chart-3/15 dark:bg-chart-3/30" },
  "chart-4": { caret: "bg-chart-4", highlight: "bg-chart-4/20 dark:bg-chart-4/30" },
  "chart-5": { caret: "bg-chart-5", highlight: "bg-chart-5/15 dark:bg-chart-5/30" },
} as const;

const SIZE = { md: "text-lg leading-relaxed sm:text-xl", lg: "text-xl leading-relaxed sm:text-2xl" } as const;

const WORD =
  "relative inline-block rounded-sm align-baseline leading-none outline-none transition-[color,translate] duration-300 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background";
const WORD_HOVER = "hover:underline hover:decoration-foreground/30 hover:decoration-1 hover:underline-offset-[6px]";

export function useReducedMotion() {
  const [reduced, setReduced] = React.useState(true);
  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** Splits text into words and gives every word a start time: a steady pace plus a breath after punctuation. */
export function getReadAlongSchedule(text: string | string[], { wordsPerSecond = 2.6, punctuationPause = 240, leadIn = 0 }: ReadAlongScheduleOptions = {}): ReadAlongSchedule {
  const paragraphs = Array.isArray(text) ? text : [text];
  const words: ReadAlongWord[] = [];
  let sentence = 0;
  paragraphs.forEach((paragraph, p) => {
    for (const raw of paragraph.split(/\s+/)) {
      if (!raw) continue;
      const endsSentence = SENTENCE_END.test(raw);
      const pause = endsSentence ? punctuationPause : CLAUSE_END.test(raw) ? punctuationPause / 2 : 0;
      words.push({ text: raw, index: words.length, paragraph: p, sentence, pause });
      if (endsSentence) sentence += 1;
    }
  });
  const step = 1 / Math.max(0.1, wordsPerSecond);
  const timings: number[] = [];
  let cursor = Math.max(0, leadIn);
  for (const word of words) {
    timings.push(cursor);
    cursor += step + Math.max(0, word.pause) / 1000;
  }
  return { words, timings, duration: cursor };
}

/** -1 before the first word, `timings.length` once the speech is over, otherwise the word being spoken at `time`. */
export function readAlongIndexAt(time: number, timings: number[], duration: number): number {
  const first = timings[0];
  if (first === undefined || time < first) return -1;
  if (time >= duration) return timings.length;
  let low = 0;
  let high = timings.length - 1;
  while (low < high) {
    const mid = (low + high + 1) >> 1;
    if ((timings[mid] ?? Number.POSITIVE_INFINITY) <= time) low = mid;
    else high = mid - 1;
  }
  return low;
}

type WordProps = {
  word: ReadAlongWord;
  state: ReadAlongWordState;
  tone: ReadAlongTone;
  dim: boolean;
  reduced: boolean;
  tabbable: boolean;
  register: (node: HTMLButtonElement | null) => void;
  onSelect: () => void;
};

function Word({ word, state, tone, dim, reduced, tabbable, register, onSelect }: WordProps) {
  const highlightRef = React.useRef(null as HTMLSpanElement | null);
  const current = state === "current";

  React.useLayoutEffect(() => {
    const node = highlightRef.current;
    if (!current || !node || reduced || typeof node.animate !== "function") return;
    const animation = node.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], { duration: HIGHLIGHT_GROW, easing: EASE });
    return () => animation.cancel();
  }, [current, reduced]);

  return (
    <button
      ref={register}
      type="button"
      data-word
      data-index={word.index}
      data-state={state}
      data-pause={word.pause > 0 ? word.pause : undefined}
      tabIndex={tabbable ? 0 : -1}
      onClick={onSelect}
      className={`${WORD} ${current ? "-translate-y-0.5 motion-reduce:translate-y-0" : WORD_HOVER} ${state === "upcoming" && dim ? "text-muted-foreground/70" : "text-foreground"}`}
    >
      <span
        ref={highlightRef}
        data-highlight
        aria-hidden="true"
        className={`pointer-events-none absolute -inset-x-1.5 -inset-y-0.5 origin-left rounded-md transition-opacity duration-200 motion-reduce:transition-none ${TONE[tone].highlight} ${current ? "opacity-100" : "opacity-0"}`}
      />
      <span className="relative">{word.text}</span>
    </button>
  );
}

export function ReadAlongText({
  text,
  progress,
  currentTime,
  duration,
  timings: timingsProp,
  playing,
  wordsPerSecond = 2.6,
  punctuationPause = 240,
  leadIn = 0,
  onProgressChange,
  onWord,
  onSeek,
  onEnd,
  tone = "chart-1",
  size = "lg",
  dimUpcoming = true,
  caret: showCaret = true,
  className = "",
  onKeyDown,
  onBlur,
  ref,
  ...rest
}: ReadAlongTextProps) {
  const reduced = useReducedMotion();
  const textKey = Array.isArray(text) ? text.join("\n") : text;
  const schedule = React.useMemo(() => getReadAlongSchedule(text, { wordsPerSecond, punctuationPause, leadIn }), [textKey, wordsPerSecond, punctuationPause, leadIn]);
  const { words } = schedule;
  const ownTimings = timingsProp !== undefined && timingsProp.length === words.length ? timingsProp : null;
  const timings = ownTimings ?? schedule.timings;
  const total = duration ?? (ownTimings ? (ownTimings[ownTimings.length - 1] ?? 0) + 1 / Math.max(0.1, wordsPerSecond) : schedule.duration);
  const timingsKey = ownTimings ? ownTimings.join(",") : "auto";
  const paragraphCount = Array.isArray(text) ? text.length : 1;

  const clock = playing !== undefined;
  const [clockIndex, setClockIndex] = React.useState(-1);
  const clockTime = React.useRef(0);
  const anchor = React.useRef({ base: 0, startedAt: 0 });
  const callbacks = React.useRef({ onProgressChange, onWord, onEnd });
  React.useEffect(() => {
    callbacks.current = { onProgressChange, onWord, onEnd };
  });

  const mode = clock ? "clock" : currentTime !== undefined ? "time" : progress !== undefined ? "progress" : "idle";
  const time = clock ? clockTime.current : currentTime !== undefined ? currentTime : progress !== undefined ? Math.min(1, Math.max(0, progress)) * total : -1;
  const index = clock ? clockIndex : readAlongIndexAt(time, timings, total);
  const indexRef = React.useRef(index);
  indexRef.current = index;

  // Convenience clock: only runs while `playing`; a host with real audio passes currentTime instead and this never starts.
  React.useEffect(() => {
    if (!clock || !playing) return;
    if (clockTime.current >= total) clockTime.current = 0;
    anchor.current = { base: clockTime.current, startedAt: performance.now() };
    let frame = 0;
    const tick = (now: number) => {
      const current = Math.min(total, anchor.current.base + (now - anchor.current.startedAt) / 1000);
      clockTime.current = current;
      const next = readAlongIndexAt(current, timings, total);
      setClockIndex((previous) => (previous === next ? previous : next));
      callbacks.current.onProgressChange?.(total > 0 ? current / total : 1, current);
      if (current >= total) {
        callbacks.current.onEnd?.();
        return;
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [clock, playing, total, timingsKey]);

  React.useEffect(() => {
    const word = words[index];
    if (word) callbacks.current.onWord?.(index, word.text);
  }, [index, words]);

  const rootRef = React.useRef(null as HTMLDivElement | null);
  const caretRef = React.useRef(null as HTMLSpanElement | null);
  const wordRefs = React.useRef([] as (HTMLButtonElement | null)[]);
  const lastBox = React.useRef(null as Box | null);
  const caretAnimation = React.useRef(null as Animation | null);
  const seekFlight = React.useRef(false);

  const boxOf = (target: number): Box | null => {
    const node = wordRefs.current[target];
    if (!node) return null;
    return { left: node.offsetLeft, top: node.offsetTop + node.offsetHeight + CARET_GAP, width: node.offsetWidth };
  };
  const place = (box: Box) => {
    const node = caretRef.current;
    if (!node) return;
    node.style.transform = `translate(${box.left}px, ${box.top}px)`;
    node.style.width = `${box.width}px`;
  };

  // One caret for the whole text: on the same line it slides (FLIP); on a line change it retracts into the old word and extends from the new line's start, so it never crosses glyphs.
  React.useLayoutEffect(() => {
    const node = caretRef.current;
    const to = index >= 0 && index < words.length ? boxOf(index) : null;
    const from = lastBox.current;
    lastBox.current = to;
    const flight = seekFlight.current ? CARET_FLIGHT : CARET_SLIDE;
    seekFlight.current = false;
    if (!node || !to) return;
    place(to);
    if (!from || reduced || typeof node.animate !== "function") return;
    caretAnimation.current?.cancel();
    const sameLine = Math.abs(from.top - to.top) < 1;
    caretAnimation.current = sameLine
      ? node.animate([
          { transform: `translate(${from.left}px, ${from.top}px)`, width: `${from.width}px` },
          { transform: `translate(${to.left}px, ${to.top}px)`, width: `${to.width}px` },
        ], { duration: flight, easing: EASE })
      : node.animate([
          { transform: `translate(${from.left}px, ${from.top}px)`, width: `${from.width}px`, opacity: 1, easing: "cubic-bezier(0.4, 0, 1, 1)" },
          { transform: `translate(${from.left + from.width}px, ${from.top}px)`, width: "0px", opacity: 1, offset: 0.45 },
          { transform: `translate(${to.left}px, ${to.top}px)`, width: "0px", opacity: 0, offset: 0.5, easing: EASE },
          { transform: `translate(${to.left}px, ${to.top}px)`, width: `${to.width}px`, opacity: 1 },
        ], { duration: flight });
  }, [index, words.length, reduced]);

  React.useEffect(() => {
    const root = rootRef.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      const box = boxOf(indexRef.current);
      if (!box) return;
      caretAnimation.current?.cancel();
      lastBox.current = box;
      place(box);
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => () => caretAnimation.current?.cancel(), []);

  const seek = (target: number) => {
    const at = timings[target];
    if (at === undefined) return;
    seekFlight.current = true;
    if (clock) {
      clockTime.current = at;
      anchor.current = { base: at, startedAt: performance.now() };
      setClockIndex(target);
    }
    onSeek?.(target, at, total > 0 ? at / total : 1);
  };

  const [focusIndex, setFocusIndex] = React.useState(null as number | null);
  const tabbableIndex = focusIndex ?? Math.min(words.length - 1, Math.max(0, index));

  const handleKeyDown: DivProps["onKeyDown"] = (event) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    const target = event.target as HTMLElement;
    if (!target.hasAttribute("data-word")) return;
    const current = Number(target.dataset.index);
    if (Number.isNaN(current)) return;
    let next = -1;
    if (event.key === "ArrowRight") next = Math.min(words.length - 1, current + 1);
    else if (event.key === "ArrowLeft") next = Math.max(0, current - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = words.length - 1;
    if (next < 0) return;
    event.preventDefault();
    setFocusIndex(next);
    wordRefs.current[next]?.focus();
  };

  const handleBlur: DivProps["onBlur"] = (event) => {
    onBlur?.(event);
    if (!rootRef.current?.contains(event.relatedTarget as Node | null)) setFocusIndex(null);
  };

  const sentenceIndex = words[index]?.sentence ?? -1;
  const sentenceText = React.useMemo(
    () => (sentenceIndex < 0 ? "" : words.filter((word) => word.sentence === sentenceIndex).map((word) => word.text).join(" ")),
    [sentenceIndex, words],
  );
  const caretVisible = showCaret && index >= 0 && index < words.length;
  const stage = index < 0 ? "idle" : index >= words.length ? "ended" : "reading";

  return (
    <div
      {...rest}
      ref={(node) => {
        rootRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) (ref as { current: HTMLDivElement | null }).current = node;
      }}
      role="group"
      aria-roledescription="read-along text"
      data-slot="read-along-text"
      data-index={index}
      data-count={words.length}
      data-mode={mode}
      data-stage={stage}
      data-tone={tone}
      onKeyDown={handleKeyDown}
      onBlur={handleBlur}
      className={`relative w-full text-foreground ${SIZE[size]} ${className}`}
    >
      {Array.from({ length: paragraphCount }, (_, p) => (
        <p key={p} data-paragraph={p} className={p > 0 ? "mt-4" : undefined}>
          {words.filter((word) => word.paragraph === p).map((word, position) => (
            <React.Fragment key={word.index}>
              {position > 0 ? " " : null}
              <Word
                word={word}
                state={word.index < index ? "done" : word.index === index ? "current" : "upcoming"}
                tone={tone}
                dim={dimUpcoming}
                reduced={reduced}
                tabbable={word.index === tabbableIndex}
                register={(node) => {
                  wordRefs.current[word.index] = node;
                }}
                onSelect={() => seek(word.index)}
              />
            </React.Fragment>
          ))}
        </p>
      ))}
      <span
        ref={caretRef}
        data-caret
        data-visible={caretVisible ? "true" : "false"}
        aria-hidden="true"
        className={`pointer-events-none absolute left-0 top-0 h-0.5 w-0 rounded-full will-change-transform transition-opacity duration-200 motion-reduce:transition-none ${TONE[tone].caret} ${caretVisible ? "opacity-100" : "opacity-0"}`}
      />
      <span role="status" aria-live="polite" className="sr-only">{sentenceText}</span>
    </div>
  );
}

export default ReadAlongText;

